package main

import (
	"bufio"
	"errors"
	"fmt"
	"os"
)

var ErrNotFound = errors.New("見つかりません")

func find(name string) error {
	if name == "gopher" {
		return nil
	}
	// 文脈を足しつつ、%w で原因の ErrNotFound を包んで返します
	return fmt.Errorf("検索 %s: %w", name, ErrNotFound)
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	name := sc.Text()

	// ここから下を書く: find を呼び、成功なら「<名前> が見つかりました」、
	// 失敗ならエラーを出力し、errors.Is で原因を判定する
	_ = name
	_ = fmt.Println
}

exercise.answer:
// lesson24 ch03 解答
package main

import (
	"bufio"
	"errors"
	"fmt"
	"os"
)

var ErrNotFound = errors.New("見つかりません")

func find(name string) error {
	if name == "gopher" {
		return nil
	}
	return fmt.Errorf("検索 %s: %w", name, ErrNotFound)
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	name := sc.Text()

	err := find(name)
	if err == nil {
		fmt.Println(name, "が見つかりました")
		return
	}
	// %w で包んだので、メッセージには文脈が足されています。
	// それでも errors.Is なら「原因が ErrNotFound か」を判定できます。
	// エラーメッセージの文字列比較で判定しないのが Go の作法です。
	fmt.Println(err)
	if errors.Is(err, ErrNotFound) {
		fmt.Println("原因は ErrNotFound です")
	}
}
